(5, '<B>MODE SPOSE INC<br />\r\n18136 J A BOMBARDIER<br />\r\nMIRABEL, QC, J7J0H5<br />\r\nCANADA<br />\r\n<br />\r\nThank You.<br />\r\n', 'vendor'),
(7, 'Thank you very much for your order(s)<br />\r\nPlease find order confirmation below.<br />\r\nFeel free to contact us, if you have any questions.<br />\r\n<br />\r\nMODE SPOSE INC<br />\r\n450-818-7078<br />\r\n<br />\r\n', 'customer'),
(8, 'Thank you very much for your order(s)<br />\r\nPlease find order confirmation below.<br />\r\nIf your order is from current stock, it will ship soon.<br />\r\nIf it is on the way to us, we will ship as soon as it is received (About 6-8 weeks or maybe sooner).<br />\r\n<br />\r\nFeel free to contact us, if you have any questions.<br />\r\n<br />\r\nMODE SPOSE INC<br />\r\n450-818-7078<br />', 'stock_customer');
